import { useRouter } from "next/router"
import { useEffect, useState } from "react"
import { androidFloatWindowData } from "./data";
import { Log, useTranslation } from "@fanfanlo";
import { WindowConfEditor } from "./WindowConfEditor";
import { WindowConf, createWindowConfCopy } from "@droid/android";
import toast from "react-hot-toast";
import { Box } from "@mui/material";

const fileLog = new Log(false, 'EditWindowContent.tsx');
export function EditWindowContent(){
    const uiLog = fileLog.sub(false, 'EditWindowContent');
    const {t} = useTranslation('homepage/components/android-float/window/content');
    const router = useRouter()
    const [windowConf, setWindowConf] = useState<WindowConf | null>(null)
    const [noWindowId, setNoWindowId] = useState(false);
    const [windowConfNotFound, setWindowConfNotFound] = useState(false);
    const {windowId} = router.query;
    useEffect(()=>{
        const effLog = uiLog.sub(true, 'useEffect-init');
        effLog.log('Editing window id:', windowId);
        if(!windowId){
          setNoWindowId(true);
          toast.error('No windowId provided in query parameters.');
            return;
        }
        androidFloatWindowData.init();
        const windowConf = androidFloatWindowData.data.windowData.windowList.find(w=>w.windowId === windowId);
        effLog.log('Loaded window config for editing:', windowConf);
        if(!windowConf){
            setWindowConfNotFound(true);
            toast.error(t('EditWindowContent.windowConfNotFound'));
            return;
        }

        // 使用createWindowConfCopy补齐所有缺失的属性
        const mergedConf = createWindowConfCopy(windowConf);
        effLog.log('Merged config with default values:', mergedConf);
        setWindowConf(mergedConf);
    }, [])
  return <Box>
    {noWindowId && <Box>{t("EditWindowContent.noWindowId")}</Box>}
    {windowConfNotFound && <Box>{t("EditWindowContent.windowConfNotFound")}</Box>}
    {windowConf && <WindowConfEditor windowConf={windowConf} />}
  </Box>
}   