// ============ 标签辅助组件 ============

// 必选标签组件
function RequiredLabel({ label, description }: { label: string; description?: string }) {
  const content = (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
      <Typography>{label}</Typography>
      <Typography sx={{ color: 'error.main', fontWeight: 'bold' }}>*</Typography>
    </Box>
  );

  if (description) {
    return (
      <Tooltip title={description} arrow>
        {content}
      </Tooltip>
    );
  }
  return content;
}

// 可选标签组件
function OptionalLabel({ label, description }: { label: string; description?: string }) {
  const content = (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
      <Typography>{label}</Typography>
      <Typography sx={{ color: 'text.secondary', fontSize: '0.875rem' }}>(可选)</Typography>
    </Box>
  );

  if (description) {
    return (
      <Tooltip title={description} arrow>
        {content}
      </Tooltip>
    );
  }
  return content;
}

// Section 标题组件
function SectionTitle({ title, count }: { title: string; count?: number }) {
  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 2, mb: 1.5 }}>
      <Typography variant="subtitle1" sx={{ fontWeight: 'bold', color: 'primary.main' }}>
        {title}
      </Typography>
      {count && (
        <Typography sx={{ color: 'text.secondary', fontSize: '0.875rem' }}>
          ({count})
        </Typography>
      )}
    </Box>
  );
}



// WebViewConf UI
