// Main WindowConf UI
export function WindowConfUI({ windowConf }: IWindowConfUI) {
  const { t } = useTranslation('droid-android/android/win/content');
  const [windowType] = useProxyWatch(windowConf, 'windowType', windowConf.windowType);
  const [contentType] = useProxyWatch(windowConf, 'contentType', windowConf.contentType);
  const [htmlConf] = useProxyWatch(windowConf, 'htmlConf', windowConf.htmlConf);
  const [floatWindowConf] = useProxyWatch(windowConf, 'floatWindowConf', windowConf.floatWindowConf);
  const [windowId] = useProxyWatch(windowConf, 'windowId', windowConf.windowId);
  const [tag] = useProxyWatch(windowConf, 'tag', windowConf.tag);
  const [description] = useProxyWatch(windowConf, 'description', windowConf.description || '');
  const [forceDismissWindowTime] = useProxyWatch(windowConf, 'forceDismissWindowTime', windowConf.forceDismissWindowTime);

  useEffect(() => {
    // 9n windowType bMn�a
    let savedFloatWindowConf = windowConf.floatWindowConf;

    windowConf.floatWindowConf = undefined;

    windowConf.floatWindowConf = savedFloatWindowConf || createDefaultFloatWindowConf();
  }, [windowType]);

  return (
    <Box sx={{ p: 2 }}>
      <Stack spacing={2}>
        <Typography variant="h5" sx={{ fontWeight: 'bold', mb: 1 }}>
          {t('content.WindowConf.title')}
        </Typography>

        {/* 必选属性部分 */}
        <SectionTitle title={t('content.WindowConf.required')} count={5} />

        <Box>
          <RequiredLabel label={t('content.WindowConf.windowType')} />
          <Select
            value={windowType}
            onChange={e => {
              windowConf.windowType = e.target.value as WindowType;
            }}
            size="small"
            fullWidth
          >
            <MenuItem value={WindowType.Float}>{WindowType.Float}</MenuItem>
          </Select>
        </Box>

        <Box>
          <RequiredLabel label={t('content.WindowConf.contentType')} />
          <Select
            value={contentType}
            disabled
            size="small"
            fullWidth
          >
            <MenuItem value={ContentType.Html}>{ContentType.Html}</MenuItem>
          </Select>
        </Box>

        <Box>
          <RequiredLabel label={t('content.WindowConf.tag')} />
          <TextField
            value={tag}
            onChange={e => {
              windowConf.tag = e.target.value;
            }}
            size="small"
            fullWidth
          />
        </Box>

        <Box>
          <OptionalLabel label={t('content.WindowConf.description')} />
          <TextField
            value={description}
            onChange={e => {
              windowConf.description = e.target.value;
            }}
            size="small"
            fullWidth
            multiline
            rows={2}
          />
        </Box>

        <Box>
          <RequiredLabel label={t('content.WindowConf.windowId')} />
          <TextField
            value={windowId}
            disabled
            size="small"
            fullWidth
          />
        </Box>

        <Box>
          <RequiredLabel label={t('content.WindowConf.forceDismissWindowTime')} />
          <TextField
            type="number"
            value={forceDismissWindowTime}
            onChange={e => {
              windowConf.forceDismissWindowTime = Number(e.target.value);
            }}
            size="small"
            fullWidth
          />
        </Box>

        {/* 可选属性部分 */}
        <SectionTitle title={t('content.WindowConf.optional')} count={3} />

        {htmlConf && (
          <Box>
            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: 'primary.main' }}>
              {t('content.HtmlConf.title')}
            </Typography>
            <HtmlConfUI htmlConf={htmlConf} />
          </Box>
        )}

        {floatWindowConf && (
          <Box>
            <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: 'primary.main' }}>
              {t('content.FloatWindowConf.title')}
            </Typography>
            <FloatWindowConfUI floatWindowConf={floatWindowConf} />
          </Box>
        )}
      </Stack>
    </Box>
  );
}

