import { WindowConf, WindowType, createDefaultFloatWindowConf } from '@droid/android';
import { toProxy, useProxyWatch } from '@fanfanlo';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Button,
  Chip,
  Stack,
  Typography,
} from '@mui/material';
import { useRouter } from 'next/router';

import { ExpandMore as ExpandMoreIcon } from '@mui/icons-material';
import { useState, useEffect } from 'react';
import {
  FloatWindowConfUI,
} from './WindowConfUI';
import { BasicInfoSection } from './BasicInfoSection';
import { HtmlConfSection } from './HtmlConfSection';
import { AdvancedSection } from './AdvancedSection';
import { androidFloatWindowData } from './data';

export interface WindowConfEditorProps {
  windowConf: WindowConf;
}

/**
 * WindowConfEditor - Accordion 式编辑窗口配置
 *
 * 功能：
 * - 快速定位和编辑字段
 * - 根据 windowType 动态显示配置
 * - 必填项标记
 */
export function WindowConfEditor({ windowConf:conf }: WindowConfEditorProps) {
  const router = useRouter();
  const [windowConf] = useState<WindowConf>(toProxy(conf));
  const [expanded, setExpanded] = useState<string | false>('basic');
  const [windowType] = useProxyWatch(windowConf, 'windowType', windowConf.windowType);
  const [tag] = useProxyWatch(windowConf, 'tag', windowConf.tag);
  const [windowId] = useProxyWatch(windowConf, 'windowId', windowConf.windowId);

  console.log('WindowConfEditor: render windowType:', windowType);

  /**
   * 监听 windowType 变化，自动初始化对应的配置对象
   */
  useEffect(() => {
    console.log('WindowConfEditor: useEffect - windowType changed to:', windowType);

    if (windowType === WindowType.Float) {
      if (!windowConf.floatWindowConf) {
        console.log('WindowConfEditor: creating default FloatWindowConf');
        windowConf.floatWindowConf = createDefaultFloatWindowConf();
      }
    }
  }, [windowType, windowConf]);

  const editComfirmed = () => {
    const index = androidFloatWindowData.data.windowData.windowList.findIndex(w=>w.windowId === windowConf.windowId);
    if(index == -1){
      console.error('WindowConfEditor: editComfirmed - window config not found for windowId:', windowConf.windowId);
      return
    }
    androidFloatWindowData.data.windowData.windowList[index] = windowConf;
    console.log('WindowConfEditor: window config updated:', windowConf);
  }

  const handleConfirm = () => {
    console.log('WindowConfEditor: handleConfirm - confirming changes');
    editComfirmed();
    router.back();
  };

  const handleCancel = () => {
    console.log('WindowConfEditor: handleCancel - discarding changes');
    router.back();
  };
  /**
   * 处理 Accordion 展开/折叠
   */
  const handleAccordionChange = (panelId: string) => (event: any, isExpanded: boolean) => {
    console.log('WindowConfEditor: Accordion', panelId, 'toggled, isExpanded:', isExpanded);
    setExpanded(isExpanded ? panelId : false);
  };

  return (
    <Box>
      {/* 头部 - 显示基本信息 */}
      <Box sx={{ mb: 3, pb: 2, borderBottom: '1px solid', borderColor: 'divider' }}>
        <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
          {tag}
        </Typography>
        <Typography variant="body2" color="text.secondary">
          类型: {windowType} | ID: {windowId.substring(0, 8)}...
        </Typography>
      </Box>

      {/* Accordion 组合 */}

      {/* 基本信息 - 必填 */}
      <Accordion
        expanded={expanded === 'basic'}
        onChange={handleAccordionChange('basic')}
      >
        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
          <Chip
            label="必填"
            size="small"
            sx={{ mr: 1 }}
            color="error"
            variant="outlined"
          />
          <Typography>基本信息</Typography>
        </AccordionSummary>
        <AccordionDetails>
          <BasicInfoSection windowConf={windowConf} />
        </AccordionDetails>
      </Accordion>

      {/* HTML 内容 - 必填 */}
      <Accordion
        expanded={expanded === 'html'}
        onChange={handleAccordionChange('html')}
      >
        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
          <Chip
            label="必填"
            size="small"
            sx={{ mr: 1 }}
            color="error"
            variant="outlined"
          />
          <Typography>HTML 内容</Typography>
        </AccordionSummary>
        <AccordionDetails>
          <HtmlConfSection htmlConf={windowConf.htmlConf} />
        </AccordionDetails>
      </Accordion>

      {/* 浮窗配置 */}
      {windowType === WindowType.Float && windowConf.floatWindowConf && (
        <Accordion
          expanded={expanded === 'float'}
          onChange={handleAccordionChange('float')}
        >
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Typography>浮窗配置</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <FloatWindowConfUI floatWindowConf={windowConf.floatWindowConf} />
          </AccordionDetails>
        </Accordion>
      )}

      {/* 高级选项 */}
      <Accordion
        expanded={expanded === 'advanced'}
        onChange={handleAccordionChange('advanced')}
      >
        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
          <Typography>高级选项</Typography>
        </AccordionSummary>
        <AccordionDetails>
          <AdvancedSection windowConf={windowConf} />
        </AccordionDetails>
      </Accordion>

      {/* 操作按钮 */}
      <Stack direction="row" spacing={2} sx={{ mt: 4, justifyContent: 'flex-end' }}>
        <Button variant="outlined" onClick={handleCancel}>
          放弃
        </Button>
        <Button variant="contained" color="primary" onClick={handleConfirm}>
          确认修改
        </Button>
      </Stack>
    </Box>
  );
}
